    "description": "A wholesome, homemade Ragi Malt prepared with nutrient-dense ingredients, balanced herbs, and cold-pressed lipids for optimal vitality, metabolic support, and clinical nourishment.",
    "prepTime": "16 mins",
    "cookTime": "18 mins",
    "calories": 238,
    "protein": "7g",
    "carbs": "28g",
